/// <summary>
/// Finds a record in ISMBatchableTelemetryStatusTable based on server ID and telemetry.
/// </summary>
/// <param name="_telemetryParameterSetup">
/// The batchable telemetry parameter setup record to match on.
/// </param>
/// <param name="_serverId">
/// The server id to match on.
/// </param>
/// <param name="_forupdate">
/// A Boolean value that determines whether to read the record for update; optional.
/// </param>
/// <returns> The ISMBatchableTelemetryStatusTable record </returns>
public static ISMBatchableTelemetryStatusTable findByTelemetryAndServer(
    ISMBatchableTelemetryParameterSetup _telemetryParameterSetup,
    ServerId _serverId, 
    boolean _forupdate = false)
{
    ISMBatchableTelemetryStatusTable statusTable = null;

    if (_telemetryParameterSetup.RecId != 0 && _serverId)
    {
        statusTable.selectForUpdate(_forupdate);

        select firstonly statusTable
            where statusTable.ParameterSetup == _telemetryParameterSetup.RecId
                && statusTable.ServerId == _serverId;
    }

    return statusTable;
}

/// <summary>
/// Initialize the status records for the telemetry for all servers.
/// </summary>
/// <param name="_batchableTelemetryParameterSetup">
/// The batchable telemetry parameter setup record to initialize the status records for.
/// </param>
public static void initRecords(ISMBatchableTelemetryParameterSetup _batchableTelemetryParameterSetup)
{

    ISMBatchableTelemetryStatusTable statusTable;

    // Check if record exists for all servers
    SysServerConfig sysServerConfig;
    while select sysServerConfig
        outer join statusTable
            where statusTable.ServerId == sysServerConfig.ServerId
    {
        if (!statusTable)
        {
            ttsbegin;
            ISMBatchableTelemetryStatusTable statusTableNew;
            statusTableNew.ParameterSetup = _batchableTelemetryParameterSetup.RecId;
            statusTableNew.ServerId = sysServerConfig.ServerId;
            statusTableNew.Batch = 0;
            statusTableNew.Status = ISMBatchableTelemetryStatus::NotReady;
            if (statusTableNew.validateWrite())
            {
                statusTableNew.insert();
            }
            ttscommit;
        }
        else
        {
            // Check if task is still running, if not clean up record
            Batch batch;
            select firstonly1 RecId, Status from batch
                where batch.RecId == statusTable.Batch;
            if (batch.Status != BatchStatus::Executing)
            {
                ISMBatchableTelemetryStatusTable statusTableUpdate;
                statusTableUpdate = ISMBatchableTelemetryStatusTable::findByTelemetryAndServer(
                    _batchableTelemetryParameterSetup, sysServerConfig.ServerId, true);
                if (statusTableUpdate)
                {
                    ttsbegin;
                    statusTableUpdate.Batch = 0;
                    statusTableUpdate.Status = ISMBatchableTelemetryStatus::NotReady;
                    if (statusTableUpdate.validateWrite())
                    {
                        statusTableUpdate.update();
                    }
                    ttscommit;
                }
            }
        }
    }

    // Sometimes servers are removed in Service Fabric environments, so remove server records if needed.
    while select forupdate statusTable
        notexists join sysServerConfig
            where sysServerConfig.ServerId == statusTable.ServerId
    {
        ttsbegin;
        if (statusTable.validateDelete())
        {
            statusTable.delete();
        }
        ttscommit;
    }

    // All Server Record
    if (!ISMBatchableTelemetryStatusTable::findByTelemetryAndServer(
        _batchableTelemetryParameterSetup, ISMBatchableTelemetryConstants::AllServers))
    {
        ISMBatchableTelemetryStatusTable statusTableNew;
        ttsbegin;
        statusTableNew.ParameterSetup = _batchableTelemetryParameterSetup.RecId;
        statusTableNew.ServerId = ISMBatchableTelemetryConstants::AllServers;
        statusTableNew.Batch = 0;
        statusTableNew.Status = ISMBatchableTelemetryStatus::NotReady;
        if (statusTableNew.validateWrite())
        {
            statusTableNew.insert();
        }
        ttscommit;
    }
}

/// <summary>
/// Cleans up records in the ISMBatchableTelemetryStatusTable during a reset.
/// </summary>
/// <param name="_batchableTelemetryParameterSetup">
/// The batchable telemetry parameter setup to clean the status records for.
/// </param>
public static void cleanupStatusRecords(ISMBatchableTelemetryParameterSetup _batchableTelemetryParameterSetup)
{

    ISMBatchableTelemetryStatusTable statusTable;

    ttsbegin;
    update_recordset statusTable
        setting Batch = 0, Status = ISMBatchableTelemetryStatus::NotReady
        where statusTable.ParameterSetup == _batchableTelemetryParameterSetup.RecId;
    ttscommit;
}

/// <summary>
/// Checks if the telemetry collection batch task exists on all servers.
/// </summary>
/// <param name="_batchableTelemetryParameterSetup">
/// The parameter setup of the telemetry in question.
/// </param>
/// <returns>
/// Boolean indicating if the batch task for collecting telemetry exists on all servers
/// </returns>
public static boolean existsTaskOnAllServers(ISMBatchableTelemetryParameterSetup _batchableTelemetryParameterSetup)
{
    SysServerConfig sysServerConfig;
    ISMBatchableTelemetryStatusTable statusTable;

    // Is there a server where the status record is missing or the batch is not running?
    select firstonly RecId from sysServerConfig
        notexists join statusTable
            where statusTable.ServerId == sysServerConfig.ServerId
                && statusTable.ParameterSetup == _batchableTelemetryParameterSetup.RecId
                && statusTable.Batch != 0;
    if (sysServerConfig.RecId != 0)
    {
        return false;
    }

    return true;
}

/// <summary>
/// Updates the status in ISMBatchableTelemetryStatusTable based on server ID and telemetry.
/// </summary>
/// <param name="_batchableTelemetryParameterSetup">
/// The batchable telemetry parameter setup that identifies the telemetry to update the status for.
/// </param>
/// <param name="_serverId">
///    The server id to match on.
/// </param>
/// <param name="_status">
///    Enum SABatchTracingStatus for status.
/// </param>
public static void updateStatus(
    ISMBatchableTelemetryParameterSetup _batchableTelemetryParameterSetup,
    ServerId _serverId, 
    ISMBatchableTelemetryStatus _status)
{
    ISMBatchableTelemetryStatusTable statusTable;
    UserConnection dbConnection;

    dbConnection = new UserConnection();
    statusTable.setConnection(dbConnection);
    dbConnection.ttsbegin();

    // TODO: Can't use find method, would break the dbConnection; unclear if dbConnection is needed
    select firstonly1 forUpdate statusTable
        where statusTable.ParameterSetup == _batchableTelemetryParameterSetup.RecId
            && statusTable.ServerId == _serverId;
    if (statusTable)
    {
        statusTable.Status = _status;
        if (statusTable.validateWrite())
        {
            statusTable.update();
        }
    }
    dbConnection.ttscommit();
    dbConnection.finalize();

}

/// <summary>
/// Updates the status on the AllServers record.
/// Aggregates the status of all servers and updates the AllServers record accordingly.
/// </summary>
/// <param name="_batchableTelemetryParameterSetup">
/// The batchable telemetry parameter setup that identifies the telemetry to update the 
/// AllServers record for.
/// </param>
public static void updateStatusOfAllServersRecord(ISMBatchableTelemetryParameterSetup _batchableTelemetryParameterSetup)
{
    List serverStatusList = new List(Types::Container);
    ISMBatchableTelemetryStatus currentAggregatedStatus;

    // Create a list of states of the telemetry and the number of servers in that state.
    ISMBatchableTelemetryStatusTable statusTableGrouped;
    while select count(RecId), Status
        from statusTableGrouped
        group by statusTableGrouped.Status
        where statusTableGrouped.ServerId != ISMBatchableTelemetryConstants::AllServers
            && statusTableGrouped.ParameterSetup == _batchableTelemetryParameterSetup.RecId
    {
        container statusContainer = [statusTableGrouped.Status, statusTableGrouped.RecId];
        serverStatusList.addEnd(statusContainer);
    }

    // Determine the current aggregated state and whether an update is needed.
    ListEnumerator serverStatusEnumerator = serverStatusList.getEnumerator();
    // > If there is only one state, update with that state
    if (serverStatusList.elements() == 1)
    {
        if (serverStatusEnumerator.moveNext())
        {
            currentAggregatedStatus = conPeek(serverStatusEnumerator.current(),1);
        }
    }
    // > If there are multiple states, determine the aggregated state
    else if (serverStatusList.elements() > 1)
    {
        // TODO: Check if max number of tasks has been exceeded, if so then Batch tracing task may not have started on some servers - status is then partial
        // Confusing comment from batch tracing, unclear if no update is ok in this case
        if (!ISMBatchableTelemetryHelper::allTasksSubmitted(_batchableTelemetryParameterSetup))
        {
            return;
        }

        ISMBatchableTelemetryStatus currentStatus;

        // Determine what states occur
        boolean startedStatusFound = false;
        boolean stoppedStatusFound = false;
        boolean notReadyStatusFound = false;
        boolean otherStatusesFound = false;
        while (serverStatusEnumerator.moveNext())
        {
            currentStatus = conPeek(serverStatusEnumerator.current(), 1);
            switch(currentStatus)
            {
                case ISMBatchableTelemetryStatus::Started:
                    startedStatusFound = true;
                    break;
                case ISMBatchableTelemetryStatus::Stopped:
                    stoppedStatusFound = true;
                    break;
                case ISMBatchableTelemetryStatus::NotReady:
                    notReadyStatusFound = true;
                    break;
                default:
                    otherStatusesFound = true;
                    break;
            }
        }

        // Based on the found states, determine the aggregated state for AllServers
        if (stoppedStatusFound && notReadyStatusFound && !otherStatusesFound)
        {
            // Some servers didn't start a batch task (which sets their status to stopped), 
            // so they remain in status Not Ready, set AllServers status to Stopped
            currentAggregatedStatus = ISMBatchableTelemetryStatus::Stopped;
        }
        else if (startedStatusFound && notReadyStatusFound && !otherStatusesFound)
        {
            // Some servers didn't start a batch task, so remain in status Not Ready, 
            // set AllServers status to Partially Started as tracing started
            currentAggregatedStatus = ISMBatchableTelemetryStatus::StartedPartially;
        }
        else if (notReadyStatusFound && otherStatusesFound && currentStatus != ISMBatchableTelemetryStatus::NotReady)
        {
            // It could be that some servers were not started, but some were, 
            // so need to make sure status isn't set to NotReady by mistake
            currentAggregatedStatus = currentStatus;
        }
        else
        {
            currentAggregatedStatus = currentStatus;
        }
    }

    ISMBatchableTelemetryStatusTable allServersStatusTable = ISMBatchableTelemetryStatusTable::findByTelemetryAndServer(
        _batchableTelemetryParameterSetup, ISMBatchableTelemetryConstants::AllServers);

    if (allServersStatusTable.Status == currentAggregatedStatus)
    {
        return; // No update needed
    }

    // Check if stop requested was set. If server states are all started, 
    // drop from refresh, do not need to update AllServers until stop completed
    if (allServersStatusTable.Status == ISMBatchableTelemetryStatus::StopRequested
        && (currentAggregatedStatus == ISMBatchableTelemetryStatus::Started
            || currentAggregatedStatus == ISMBatchableTelemetryStatus::StartedPartially))
    {
        return;
    }

    // Check if all servers are stopped and the AllServers status is NotReady. 
    // This means a telemetry collection is started and the servers are ready.
    // Now the AllServers status should be updated to StartRequested to signal the batch tasks to start.
    if (allServersStatusTable.Status == ISMBatchableTelemetryStatus::NotReady
        && currentAggregatedStatus == ISMBatchableTelemetryStatus::Stopped)
    {
        currentAggregatedStatus = ISMBatchableTelemetryStatus::StartRequested;
    }

    ISMBatchableTelemetryStatusTable::updateStatus(
        _batchableTelemetryParameterSetup, 
        ISMBatchableTelemetryConstants::AllServers, 
        currentAggregatedStatus);
}

/// <summary>
/// Start telemetry collection on all batch servers, and wait until started, the return
/// </summary>
/// <param name="_batchableTelemetryParameterSetup">
/// The batchable telemetry parameter setup to start telemetry collection for
/// </param>
public static void startTelemetryCollectionOnAllServers(
    ISMBatchableTelemetryParameterSetup _batchableTelemetryParameterSetup)
{
    ISMBatchableTelemetryStatusTable statusTable;

    while select statusTable
        where statusTable.ServerId != ISMBatchableTelemetryConstants::AllServers
            && statusTable.ParameterSetup == _batchableTelemetryParameterSetup.RecId
    {
        if (statusTable.Status == ISMBatchableTelemetryStatus::Stopped)
        {
            ISMBatchableTelemetryStatusTable::updateStatus(
                _batchableTelemetryParameterSetup,
                statusTable.ServerId,
                ISMBatchableTelemetryStatus::StartRequested);
            info(strFmt("Started telemetry collection on server %1", statusTable.ServerId));
        }
    }
}

/// <summary>
/// Sets the batch task RecId for when the telemetry task is started.
/// </summary>
/// <param name="_currentTask">
/// The current batch task.
/// </param>
/// <returns>Boolean is update was successful</returns>
public static boolean tryUpdateBatchRecId(
    Batch _currentTask,
    ISMBatchableTelemetryParameterSetup _batchableTelemetryParameterSetup)
{
    ISMBatchableTelemetryStatusTable statusTable;
    boolean updateSuccessful = false;

    try
    {
        ttsbegin;
        statusTable.readCommittedLock(true);
        statusTable.readPast(true);
        // TODO: Can't use find method, would break the dbConnection; unclear if dbConnection is needed
        select firstonly1 forupdate statusTable
            where statusTable.ParameterSetup == _batchableTelemetryParameterSetup.RecId
                && statusTable.ServerId == _currentTask.ServerId;
        if (statusTable)
        {
            // Record for server exists, see if there is already another task running 
            // on this server ready for telemetry
            if (statusTable.Batch == 0)
            {
                statusTable.Batch = _currentTask.RecId;
                statusTable.Status = ISMBatchableTelemetryStatus::Stopped;
                if (statusTable.validateWrite())
                {
                    statusTable.update();
                    updateSuccessful = true;
                }
            }
        }
        else
        {
            statusTable.ServerId = _currentTask.ServerId;
            statusTable.ParameterSetup = _batchableTelemetryParameterSetup.RecId;
            statusTable.Batch = _currentTask.RecId;
            statusTable.Status = ISMBatchableTelemetryStatus::Stopped;
            if (statusTable.validateWrite())
            {
                statusTable.insert();
                updateSuccessful = true;
            }
        }
        ttscommit;
    }
    catch (Exception::Error)
    {
        ttsabort;
        exceptionTextFallThrough();
    }

    return updateSuccessful;
}

/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}
